from __future__ import annotations

import re
from pathlib import Path

NEW_FUNCTION = 'def _circular_scribble_paths(\n    image: Image.Image,\n    recipe: ProjectRecipe,\n    preview: RasterPreview,\n    checkpoint: ProgressCallback | None,\n) -> VectorizationResult:\n    """Trace one organic tone-aware path through a smooth space-filling carrier."""\n\n    settings = recipe.raster_vectorize\n    placement = preview.placement\n    maximum_radius = min(\n        settings.squiggle_amplitude_mm,\n        placement.width_mm / 4,\n        placement.height_mm / 4,\n    )\n    if maximum_radius <= 0:\n        return VectorizationResult(paths=[], removed_segments=1)\n\n    # The previous implementation completed a low-resolution polygon at each point on a\n    # horizontal scanline. Build a tone-biased, low-discrepancy carrier instead, order it\n    # with a Hilbert key, round it, and continuously orbit that moving centre. This keeps\n    # the path deterministic while removing rows, straight joins, and repeated octagons.\n    edge_padding = maximum_radius * 1.5\n    min_center_x = placement.x_mm + edge_padding\n    max_center_x = placement.x_mm + placement.width_mm - edge_padding\n    min_center_y = placement.y_mm + edge_padding\n    max_center_y = placement.y_mm + placement.height_mm - edge_padding\n    if min_center_x >= max_center_x or min_center_y >= max_center_y:\n        return VectorizationResult(paths=[], removed_segments=1)\n\n    inner_width = max_center_x - min_center_x\n    inner_height = max_center_y - min_center_y\n    inner_area = inner_width * inner_height\n    light_pitch = max(0.2, settings.squiggle_wavelength_mm)\n    minimum_radius = maximum_radius * 0.32\n    samples_per_turn = {"draft": 20, "standard": 28, "export": 36}[recipe.mode.quality]\n    point_budget = WORKING_PIXEL_LIMITS[recipe.mode.quality] // 2\n    pixels = cast(Any, image.load())\n    source_seed = int(preview.source_asset_sha256[:8], 16) / 0xFFFFFFFF\n\n    def clamp_point(point: FloatPoint) -> FloatPoint:\n        return (\n            min(placement.x_mm + placement.width_mm, max(placement.x_mm, point[0])),\n            min(placement.y_mm + placement.height_mm, max(placement.y_mm, point[1])),\n        )\n\n    def darkness_at(point: FloatPoint) -> float:\n        raw_darkness = (\n            1.0\n            - _sample_luminance(\n                pixels,\n                image.width,\n                image.height,\n                placement,\n                point,\n            )\n            / 255.0\n        )\n        floor = settings.squiggle_min_darkness\n        if raw_darkness <= floor:\n            return 0.0\n        return min(1.0, max(0.0, (raw_darkness - floor) / max(1e-9, 1.0 - floor)))\n\n    def unit_hash(index: int, channel: int) -> float:\n        value = math.sin(\n            (index + 1) * 12.9898\n            + channel * 78.233\n            + source_seed * 37.719\n        ) * 43758.5453\n        return value - math.floor(value)\n\n    def organic_noise(value: float, phase: float) -> float:\n        return (\n            0.52 * math.sin(value * 0.73 + phase * 1.91)\n            + 0.30 * math.sin(value * 1.87 + phase * 0.67 + 1.3)\n            + 0.18 * math.sin(value * 3.11 + phase * 1.23 + 2.1)\n        )\n\n    hilbert_side = 1024\n\n    def hilbert_index(point: FloatPoint) -> int:\n        x = min(\n            hilbert_side - 1,\n            max(0, int((point[0] - min_center_x) / inner_width * hilbert_side)),\n        )\n        y = min(\n            hilbert_side - 1,\n            max(0, int((point[1] - min_center_y) / inner_height * hilbert_side)),\n        )\n        index = 0\n        scale = hilbert_side // 2\n        while scale > 0:\n            x_bit = 1 if x & scale else 0\n            y_bit = 1 if y & scale else 0\n            index += scale * scale * ((3 * x_bit) ^ y_bit)\n            if y_bit == 0:\n                if x_bit == 1:\n                    x = scale - 1 - x\n                    y = scale - 1 - y\n                x, y = y, x\n            scale //= 2\n        return index\n\n    anchor_spacing = max(\n        0.25,\n        settings.squiggle_spacing_mm * 1.35,\n        maximum_radius * 2.0,\n        light_pitch * 0.45,\n    )\n    anchor_limit = {"draft": 900, "standard": 1800, "export": 3200}[recipe.mode.quality]\n    anchor_count = max(\n        16,\n        min(anchor_limit, round(inner_area / (anchor_spacing * anchor_spacing))),\n    )\n    anchors: list[FloatPoint] = []\n    attempt = 0\n    maximum_attempts = anchor_count * 8\n    alpha = 0.7548776662466927\n    beta = 0.5698402909980532\n    tone_bias_enabled = settings.squiggle_modulation in {"frequency", "both"}\n\n    while len(anchors) < anchor_count and attempt < maximum_attempts:\n        u = (0.5 + source_seed * 0.113 + alpha * (attempt + 1)) % 1.0\n        v = (0.5 + source_seed * 0.271 + beta * (attempt + 1)) % 1.0\n        u = (u + 0.027 * math.sin(2 * math.pi * v * 3.17 + attempt * 0.013)) % 1.0\n        v = (\n            v\n            + 0.027 * math.sin(2 * math.pi * u * 2.73 + attempt * 0.017 + 1.2)\n        ) % 1.0\n        point = (\n            min_center_x + u * inner_width,\n            min_center_y + v * inner_height,\n        )\n        darkness = darkness_at(point)\n        acceptance = 0.35 + 0.65 * math.sqrt(darkness) if tone_bias_enabled else 1.0\n        if unit_hash(attempt, 7) <= acceptance:\n            anchors.append(point)\n        attempt += 1\n        if attempt % 64 == 0:\n            _checkpoint(\n                checkpoint,\n                "circular-scribble-carrier",\n                len(anchors),\n                anchor_count,\n            )\n\n    while len(anchors) < anchor_count:\n        u = (0.5 + source_seed * 0.113 + alpha * (attempt + 1)) % 1.0\n        v = (0.5 + source_seed * 0.271 + beta * (attempt + 1)) % 1.0\n        anchors.append(\n            (\n                min_center_x + u * inner_width,\n                min_center_y + v * inner_height,\n            )\n        )\n        attempt += 1\n\n    anchors.sort(key=lambda point: (hilbert_index(point), point[0], point[1]))\n    carrier = anchors\n    for _ in range(2):\n        rounded = [carrier[0]]\n        for first, second in pairwise(carrier):\n            rounded.extend(\n                (\n                    (\n                        first[0] * 0.75 + second[0] * 0.25,\n                        first[1] * 0.75 + second[1] * 0.25,\n                    ),\n                    (\n                        first[0] * 0.25 + second[0] * 0.75,\n                        first[1] * 0.25 + second[1] * 0.75,\n                    ),\n                )\n            )\n        rounded.append(carrier[-1])\n        carrier = rounded\n\n    average_anchor_spacing = math.sqrt(inner_area / anchor_count)\n    drift_amplitude = average_anchor_spacing * 0.08\n    carrier = [\n        (\n            min(\n                max_center_x,\n                max(\n                    min_center_x,\n                    point[0]\n                    + drift_amplitude\n                    * organic_noise(index * 0.031, 4.1 + source_seed),\n                ),\n            ),\n            min(\n                max_center_y,\n                max(\n                    min_center_y,\n                    point[1]\n                    + drift_amplitude\n                    * organic_noise(index * 0.027, 7.9 + source_seed),\n                ),\n            ),\n        )\n        for index, point in enumerate(carrier)\n    ]\n\n    cumulative_distance = [0.0]\n    for first, second in pairwise(carrier):\n        cumulative_distance.append(\n            cumulative_distance[-1] + _distance(first, second)\n        )\n    total_distance = cumulative_distance[-1]\n    if total_distance <= 0:\n        return VectorizationResult(paths=[], removed_segments=1)\n\n    dark_pitch = max(\n        0.08,\n        min(light_pitch * 0.055, maximum_radius * 0.18),\n        total_distance * samples_per_turn / point_budget,\n    )\n    angular_step = 2 * math.pi / samples_per_turn\n    distance_along = 0.0\n    carrier_index = 0\n    phase = 2 * math.pi * unit_hash(0, 11)\n    radius = maximum_radius\n    pitch = light_pitch\n    points: list[FloatPoint] = []\n\n    while distance_along <= total_distance and len(points) < point_budget:\n        while (\n            carrier_index + 1 < len(cumulative_distance)\n            and cumulative_distance[carrier_index + 1] < distance_along\n        ):\n            carrier_index += 1\n        if carrier_index >= len(carrier) - 1:\n            break\n\n        first = carrier[carrier_index]\n        second = carrier[carrier_index + 1]\n        segment_length = max(\n            1e-9,\n            cumulative_distance[carrier_index + 1]\n            - cumulative_distance[carrier_index],\n        )\n        ratio = (\n            distance_along - cumulative_distance[carrier_index]\n        ) / segment_length\n        center = (\n            first[0] + (second[0] - first[0]) * ratio,\n            first[1] + (second[1] - first[1]) * ratio,\n        )\n        darkness = darkness_at(center)\n        target_radius = (\n            maximum_radius - (maximum_radius - minimum_radius) * darkness\n            if settings.squiggle_modulation in {"amplitude", "both"}\n            else maximum_radius\n        )\n        target_pitch = (\n            light_pitch\n            - (light_pitch - dark_pitch) * math.pow(darkness, 1.15)\n            if settings.squiggle_modulation in {"frequency", "both"}\n            else light_pitch\n        )\n        radius += (target_radius - radius) * 0.13\n        pitch += (target_pitch - pitch) * 0.10\n\n        progress = distance_along / max(maximum_radius, 0.1)\n        radius_noise = organic_noise(progress * 0.15, 2.4 + source_seed)\n        phase_noise = organic_noise(progress * 0.08, 8.3 + source_seed)\n        loop_radius = radius * (1 + 0.18 * radius_noise)\n        harmonic = (\n            1\n            + 0.12 * math.sin(3 * phase + progress * 0.031)\n            + 0.045 * math.sin(5 * phase - progress * 0.021)\n        )\n        rotation = 0.45 * organic_noise(progress * 0.032, 5.7 + source_seed)\n        radius_x = (\n            loop_radius\n            * (0.91 + 0.11 * organic_noise(progress * 0.07, 1.1 + source_seed))\n            * harmonic\n        )\n        radius_y = (\n            loop_radius\n            * (0.86 + 0.14 * organic_noise(progress * 0.11, 4.1 + source_seed))\n            * harmonic\n        )\n        offset_x = radius_x * math.cos(phase)\n        offset_y = radius_y * math.sin(phase + 0.06 * phase_noise)\n        cos_rotation = math.cos(rotation)\n        sin_rotation = math.sin(rotation)\n        points.append(\n            clamp_point(\n                (\n                    center[0] + cos_rotation * offset_x - sin_rotation * offset_y,\n                    center[1] + sin_rotation * offset_x + cos_rotation * offset_y,\n                )\n            )\n        )\n\n        phase += angular_step * (1 + 0.10 * phase_noise)\n        distance_along += max(0.015, pitch / samples_per_turn)\n        if len(points) % 1024 == 0:\n            _checkpoint(\n                checkpoint,\n                "circular-scribble-trace",\n                min(round(distance_along), round(total_distance)),\n                round(total_distance),\n            )\n\n    _checkpoint(\n        checkpoint,\n        "circular-scribble-trace",\n        round(total_distance),\n        round(total_distance),\n    )\n    deduplicated = [\n        point\n        for index, point in enumerate(points)\n        if index == 0 or point != points[index - 1]\n    ]\n    return VectorizationResult(\n        paths=[deduplicated] if len(deduplicated) >= 2 else [],\n        removed_segments=0 if len(deduplicated) >= 2 else 1,\n    )'
NEW_TESTS = 'from __future__ import annotations\n\nimport io\nimport math\n\nfrom PIL import Image\nfrom plotter_core.importers.raster_vectorize import vectorize_raster\nfrom plotter_core.models import DesignDocument, LineCommand, MoveCommand, ProjectRecipe\nfrom plotter_core.planning import build_plot_plan\n\n\ndef _gradient_fixture() -> bytes:\n    image = Image.new("L", (96, 64), 255)\n    for y in range(image.height):\n        for x in range(image.width):\n            image.putpixel((x, y), round(255 * x / (image.width - 1)))\n    encoded = io.BytesIO()\n    image.save(encoded, format="PNG")\n    return encoded.getvalue()\n\n\ndef _recipe() -> ProjectRecipe:\n    recipe = ProjectRecipe(project_id="raster-circular-scribble", name="Circular scribble")\n    recipe.mode.mode_id = "import.raster"\n    recipe.mode.quality = "draft"\n    recipe.page.preset = "custom"\n    recipe.page.width_mm = 90\n    recipe.page.height_mm = 70\n    recipe.page.margin_mm = 5\n    recipe.raster_preprocess.sampling_pixels_per_pen_width = 1\n    recipe.raster_vectorize.algorithm = "circular-scribble"\n    recipe.raster_vectorize.squiggle_spacing_mm = 4\n    recipe.raster_vectorize.squiggle_amplitude_mm = 1.4\n    recipe.raster_vectorize.squiggle_wavelength_mm = 6\n    recipe.raster_vectorize.squiggle_modulation = "both"\n    return recipe\n\n\ndef _points(document: DesignDocument) -> list[tuple[float, float]]:\n    return [\n        (command.point.x, command.point.y)\n        for path in document.layers[0].paths\n        for command in path.commands\n        if isinstance(command, MoveCommand | LineCommand)\n    ]\n\n\ndef test_circular_scribble_is_deterministic_single_path_and_tone_aware() -> None:\n    recipe = _recipe()\n    content = _gradient_fixture()\n    first = vectorize_raster(content, "image/png", recipe, source_sha256="9" * 64)\n    second = vectorize_raster(content, "image/png", recipe, source_sha256="9" * 64)\n\n    assert first.metadata.normalized_sha256 == second.metadata.normalized_sha256\n    assert first.metadata.generator_version == "1.1.0"\n    assert first.layers[0].layer_id == "layer-raster-circular-scribble"\n    assert first.layers[0].metadata["path_count"] == 1\n    assert len(first.layers[0].paths) == 1\n\n    path = first.layers[0].paths[0]\n    assert not path.closed\n    assert isinstance(path.commands[0], MoveCommand)\n    assert all(isinstance(command, LineCommand) for command in path.commands[1:])\n    assert len(path.commands) > 2_000\n\n    points = _points(first)\n    assert all(\n        math.isfinite(x)\n        and math.isfinite(y)\n        and recipe.page.margin_mm <= x <= recipe.page.width_mm - recipe.page.margin_mm\n        and recipe.page.margin_mm <= y <= recipe.page.height_mm - recipe.page.margin_mm\n        for x, y in points\n    )\n    midpoint = recipe.page.width_mm / 2\n    dark_vertices = sum(x < midpoint for x, _ in points)\n    light_vertices = sum(x >= midpoint for x, _ in points)\n    assert dark_vertices > light_vertices * 1.25\n\n    plan = build_plot_plan(recipe, first)\n    assert plan.statistics.path_count == 1\n\n\ndef test_circular_scribble_tone_modulation_changes_geometry() -> None:\n    recipe = _recipe()\n    content = _gradient_fixture()\n    adaptive = vectorize_raster(content, "image/png", recipe, source_sha256="a" * 64)\n\n    recipe.raster_vectorize.squiggle_modulation = "amplitude"\n    fixed_pitch = vectorize_raster(content, "image/png", recipe, source_sha256="a" * 64)\n\n    assert adaptive.metadata.normalized_sha256 != fixed_pitch.metadata.normalized_sha256\n    assert len(adaptive.layers[0].paths[0].commands) > len(fixed_pitch.layers[0].paths[0].commands)\n\n\ndef test_circular_scribble_is_smooth_and_not_scanline_dominated() -> None:\n    recipe = _recipe()\n    design = vectorize_raster(\n        _gradient_fixture(),\n        "image/png",\n        recipe,\n        source_sha256="b" * 64,\n    )\n    points = _points(design)\n\n    segment_lengths = sorted(\n        math.hypot(second[0] - first[0], second[1] - first[1])\n        for first, second in zip(points, points[1:], strict=False)\n    )\n    percentile_95 = segment_lengths[round((len(segment_lengths) - 1) * 0.95)]\n    assert percentile_95 < 1.0\n\n    block_size = 40\n    centres: list[tuple[float, float]] = []\n    for start in range(0, len(points) - block_size + 1, block_size):\n        block = points[start : start + block_size]\n        centres.append(\n            (\n                sum(point[0] for point in block) / len(block),\n                sum(point[1] for point in block) / len(block),\n            )\n        )\n\n    orientation_bins = [0] * 12\n    for first, second in zip(centres, centres[1:], strict=False):\n        dx = second[0] - first[0]\n        dy = second[1] - first[1]\n        if math.hypot(dx, dy) <= 0.25:\n            continue\n        orientation = math.atan2(dy, dx) % math.pi\n        index = min(len(orientation_bins) - 1, int(orientation / math.pi * len(orientation_bins)))\n        orientation_bins[index] += 1\n\n    orientation_count = sum(orientation_bins)\n    assert orientation_count > 20\n    assert sum(count > 0 for count in orientation_bins) >= 10\n    assert max(orientation_bins) / orientation_count < 0.3\n'


def replace_once(path: Path, old: str, new: str) -> None:
    text = path.read_text(encoding="utf-8")
    count = text.count(old)
    if count != 1:
        raise RuntimeError(f"expected one match in {path} but found {count}")
    path.write_text(text.replace(old, new), encoding="utf-8")


def main() -> None:
    vectorizer = Path("packages/plotter_core/plotter_core/importers/raster_vectorize.py")
    text = vectorizer.read_text(encoding="utf-8")
    old_version = 'CIRCULAR_SCRIBBLE_VECTORIZER_VERSION = "1.0.0"'
    if text.count(old_version) != 1:
        raise RuntimeError("unexpected circular scribble vectorizer version")
    text = text.replace(
        old_version,
        'CIRCULAR_SCRIBBLE_VECTORIZER_VERSION = "1.1.0"',
        1,
    )
    pattern = re.compile(
        r"def _circular_scribble_paths\(\n.*?\n\ndef _interpolate\(",
        re.DOTALL,
    )
    text, count = pattern.subn(NEW_FUNCTION + "\n\n\ndef _interpolate(", text, count=1)
    if count != 1:
        raise RuntimeError("could not replace circular scribble implementation")
    vectorizer.write_text(text, encoding="utf-8")

    Path("packages/plotter_core/tests/test_circular_scribble.py").write_text(
        NEW_TESTS,
        encoding="utf-8",
    )

    replace_once(
        Path("services/api/plotterapp_api/main.py"),
        'return "import.raster", "1.1.0", run_vectorize',
        'return "import.raster", "1.2.0", run_vectorize',
    )

    app = Path("apps/web/src/App.tsx")
    replace_once(
        app,
        '<option value="circular-scribble">Circular scribble (single line)</option>',
        '<option value="circular-scribble">Organic circular scribble (single line)</option>',
    )
    replace_once(app, "              Lane spacing mm", "              Path spacing mm")
    replace_once(
        app,
        'aria-label="Circular scribble lane spacing"',
        'aria-label="Circular scribble path spacing"',
    )
    replace_once(
        app,
        """          <p className="field-help">
            Emits one continuous plotted path. Darker tones shrink the curls and reduce their
            forward pitch, increasing overlap without lifting the pen.
          </p>""",
        """          <p className="field-help">
            Emits one continuous plotted path over a rounded organic carrier. Overlap modulation
            makes darker tones use denser carrier points and shorter forward pitch; swirl-size
            modulation shrinks the curls.
          </p>""",
    )

    app_test = Path("apps/web/src/App.test.tsx")
    replace_once(
        app_test,
        """    await user.selectOptions(screen.getByLabelText("Raster vectorization algorithm"), "squiggle");
    expect(screen.getByLabelText("Raster squiggle wavelength")).toHaveValue(5);
    await user.selectOptions(screen.getByLabelText("Raster vectorization algorithm"), "dither");""",
        """    await user.selectOptions(screen.getByLabelText("Raster vectorization algorithm"), "squiggle");
    expect(screen.getByLabelText("Raster squiggle wavelength")).toHaveValue(5);
    await user.selectOptions(
      screen.getByLabelText("Raster vectorization algorithm"),
      "circular-scribble",
    );
    expect(screen.getByLabelText("Circular scribble path spacing")).toHaveValue(1.5);
    await user.selectOptions(screen.getByLabelText("Raster vectorization algorithm"), "dither");""",
    )

    replace_once(
        Path("README.md"),
        "- single-line tone-aware circular scribbles with smaller, more closely spaced loops in darker regions;",
        "- single-line organic circular scribbles using a tone-biased space-filling carrier, smaller curls, and tighter overlap in darker regions;",
    )


if __name__ == "__main__":
    main()
